// PNG assets compiled from the existing GIF and procedural ESP shapes.
// Native PNG decoding avoids Color[] construction and per-pixel VM work in OnGUI.
using System;
using UnityEngine;
namespace COW.GamePlay
{
    public partial class SceneEditBoxSelectTool
    {
        public static Texture2D MzPng(string encoded,FilterMode filter)
        {
            Texture2D texture=null;
            try{byte[] data=Convert.FromBase64String(encoded);texture=new Texture2D(2,2,TextureFormat.RGBA32,false);if(!ImageConversion.LoadImage(texture,data,true))throw new InvalidOperationException("Invalid menu PNG");texture.filterMode=filter;texture.wrapMode=TextureWrapMode.Clamp;return texture;}
            catch(Exception){if(texture!=null)UnityEngine.Object.Destroy(texture);throw;}
        }
        public static string[] MzGlassData(){return new string[]{
"",
